      seq: i + 1,
      key_id: keyId,
      method: rec.method.toUpperCase(),
      path,
      outcome,
      signature,
      canonical_sha256: canonicalSha256,
    };

    if (reason) {
      evidence.reason = reason;
    }

    out.push(evidence);
  });

  process.stdout.write(out.map((e) => `${JSON.stringify(e)}\n`).join(""));
}

